test("title-becomes-url-slug: a title is turned into a URL-safe slug", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("spaces-become-hyphens: a space between words becomes a hyphen", () => {
  assert.equal(slugify("my first post"), "my-first-post");
});

test("letters-lowercased: uppercase letters are lowercased", () => {
  assert.equal(slugify("HELLO"), "hello");
});

test("punctuation-removed: punctuation does not appear in the slug", () => {
  assert.equal(slugify("hello!"), "hello");
});

test("repeated-spaces-single-hyphen: several spaces in a row produce one hyphen", () => {
  assert.equal(slugify("hello   world"), "hello-world");
});

test("no-edge-hyphens: leading and trailing spaces leave no hyphen at the edges", () => {
  assert.equal(slugify(" hello "), "hello");
});

test("digits-kept: digits are kept in the slug", () => {
  assert.equal(slugify("top 10"), "top-10");
});

test("existing-slug-unchanged: a title that is already a slug comes back unchanged", () => {
  assert.equal(slugify("hello-world"), "hello-world");
  // The assertion above passes on a slugify that does nothing, so also require
  // that a title which is not a slug does not come back as it went in.
  assert.notEqual(slugify("Hello World"), "Hello World");
});

test("title-becomes-url-slug: a title becomes a string usable in a URL as-is", () => {
  assert.equal(slugify("My First Post"), "my-first-post");
});

test("spaces-become-hyphens: a space between words becomes a hyphen", () => {
  assert.equal(slugify("my post"), "my-post");
});

test("punctuation-removed: punctuation does not appear in the slug", () => {
  assert.equal(slugify("hello, world!"), "hello-world");
});

test("repeated-spaces-collapse: several spaces in a row give one hyphen", () => {
  assert.equal(slugify("my   post"), "my-post");
});

test("no-edge-hyphens: leading and trailing spaces leave no hyphen at the edges", () => {
  assert.equal(slugify("  hello  "), "hello");
});

test("lowercased: uppercase letters are lowercased", () => {
  assert.equal(slugify("HELLO"), "hello");
});

test("digits-kept: digits are kept", () => {
  assert.equal(slugify("top 10"), "top-10");
});

test("existing-slug-unchanged: a title that is already a slug comes back unchanged", () => {
  assert.equal(slugify("my-first-post"), "my-first-post");
  // The assertion above already passes on code that does nothing, so also
  // require that the slug was really produced by slugify.
  assert.equal(slugify("My First Post"), "my-first-post");
});

test('title-becomes-url-slug: "Hello World" becomes "hello-world"', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('spaces-become-hyphens: "a b" becomes "a-b"', () => {
  assert.equal(slugify('a b'), 'a-b');
});

test('letters-lowercased: "Hello" becomes "hello"', () => {
  assert.equal(slugify('Hello'), 'hello');
});

test('punctuation-removed: "ready?" becomes "ready"', () => {
  assert.equal(slugify('ready?'), 'ready');
});

test("hours-and-minutes-to-seconds: parseDuration(\"1h30m\") returns 5400", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("hour-part-is-3600-seconds: parseDuration(\"2h\") returns 7200", () => {
  assert.equal(parseDuration("2h"), 7200);
});

test("minute-part-is-60-seconds: parseDuration(\"45m\") returns 2700", () => {
  assert.equal(parseDuration("45m"), 2700);
});

test("hours-and-minutes-to-seconds: parseDuration(\"1h30m\") returns 5400", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("result-is-a-number: typeof parseDuration(\"1h30m\") is \"number\"", () => {
  assert.equal(typeof parseDuration("1h30m"), "number");
});

test("hours-only: parseDuration(\"2h\") returns 7200", () => {
  assert.equal(parseDuration("2h"), 7200);
});

test("minutes-only: parseDuration(\"45m\") returns 2700", () => {
  assert.equal(parseDuration("45m"), 2700);
});

test("non-duration-gives-null: parseDuration(\"abc\") returns null", () => {
  assert.equal(parseDuration("abc"), null);
  // The stub returns null for everything, so null only counts when real durations do not.
  assert.notEqual(parseDuration("1h30m"), null);
});

test("hours-and-minutes-to-seconds: \"1h30m\" returns 5400", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("hours-only: \"2h\" returns 7200", () => {
  assert.equal(parseDuration("2h"), 7200);
});

test("minutes-only: \"30m\" returns 1800", () => {
  assert.equal(parseDuration("30m"), 1800);
});

test("unreadable-text-gives-null: \"abc\" returns null", () => {
  assert.equal(parseDuration("abc"), null);
  // The stub returns null for everything, so null only counts once readable text does not.
  assert.notEqual(parseDuration("1h30m"), null);
});
